{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-nNMu8H/src/model.js","content":"/**
 * Shared data model and small helpers used by the parser and formatter.
 *
 * Every value in the parsed document is represented as a "node":
 *   { kind: 'table',   map: Map<string, Node>, headerDefined: boolean }
 *   { kind: 'aot',     items: TableNode[] }              // array of tables
 *   { kind: 'array',   items: Node[] }
 *   { kind: 'string',  value: string }
 *   { kind: 'integer', text: string }                    // normalized digits, may start with '-'
 *   { kind: 'float',   value: number }
 *   { kind: 'boolean', value: boolean }
 */

export class ParseError extends Error {
  constructor(lineNumber, reason) {
    super(`line ${lineNumber}: ${reason}`)
    this.lineNumber = lineNumber
    this.reason = reason
  }
}

export function makeTable(headerDefined = false) {
  return { kind: 'table', map: new Map(), headerDefined }
}

/** Compares two strings in ascending order by Unicode code point. */
export function cmpCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

/** Renders a path made of {kind:'key', name} and {kind:'index', i} segments. */
export function pathStr(segs) {
  let out = ''
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i]
    if (s.kind === 'index') out += `[${s.i}]`
    else out += i === 0 ? s.name : '.' + s.name
  }
  return out
}
"}

