chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-nNMu8H/src/parser.js","content":"import { ParseError, makeTable, pathStr } from './model.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

class LineParser {
  constructor(line, lineNumber) {
    this.line = line
    this.lineNumber = lineNumber
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  advance() {
    const ch = this.line[this.pos]
    this.pos++
    return ch
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  skipWSAndComment() {
    this.skipWS()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) this.pos = this.line.length
  }

  fail(reason) {
    throw new ParseError(this.lineNumber, reason)
  }
}

function findFirstNonWS(line) {
  for (let i = 0; i < line.length; i++) {
    if (line[i] !== ' ' && line[i] !== '\t') return i
  }
  return -1
}

function parseBasicString(p) {
  p.advance() // opening quote
  let out = ''
  for (;;) {
    if (p.atEnd()) p.fail('unterminated string')
    const ch = p.advance()
    if (ch === '"') return out
    if (ch === '\\') {
      if (p.atEnd()) p.fail('unterminated string')
      const esc = p.advance()
      switch (esc) {
        case '"':
          out += '"'
          break
        case '\\':
          out += '\\'
          break
        case 'n':
          out += '\n'
          break
        case 't':
          out += '\t'
          break
        case 'r':
          out += '\r'
          break
        case '0':
          out += '\0'
          break
        case 'u': {
          if (p.pos + 4 > p.line.length) p.fail('unterminated string')
          const hex = p.line.slice(p.pos, p.pos + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) p.fail('invalid escape \\u')
          p.pos += 4
          out += String.fromCharCode(parseInt(hex, 16))
          break
        }
        default:
          p.fail(`invalid escape \\${esc}`)
      }
    } else {
      out += ch
    }
  }
}

function parseLiteralString(p) {
  p.advance() // opening quote
  const start = p.pos
  while (!p.atEnd() && p.peek() !== "'") p.advance()
  if (p.atEnd()) p.fail('unterminated string')
  const out = p.line.slice(start, p.pos)
  p.advance() // closing quote
  return out
}

function parseName(p) {
  p.skipWS()
  if (p.atEnd()) p.fail('expected a name')
  const ch = p.peek()
  if (ch === '"') return parseBasicString(p)
  if (ch === "'") return parseLiteralString(p)
  if (NAME_CHAR.test(ch)) {
    const start = p.pos
    while (!p.atEnd() && NAME_CHAR.test(p.peek())) p.advance()
    return p.line.slice(start, p.pos)
  }
  p.fail('expected a name')
}

function parseDottedName(p) {
  const names = [parseName(p)]
  for (;;) {
    p.skipWS()
    if (!p.atEnd() && p.peek() === '.') {
      p.advance()
      names.push(parseName(p))
    } else break
  }
  return names
}

function normalizeInteger(token) {
  let sign = ''
  let s = token
  if (s[0] === '+' || s[0] === '-') {
    if (s[0] === '-') sign = '-'
    s = s.slice(1)
  }
  s = s.replace(/_/g, '')
  s = s.replace(/^0+(?=\d)/, '')
  if (s === '0') sign = ''
  return sign + s
}

function isDelim(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

function isTerminator(ch) {
  return ch === ',' || ch === ']' || ch === '}'
}

function parseBareValue(p) {
  const start = p.pos
  while (!p.atEnd() && !isDelim(p.peek())) p.advance()
  const token = p.line.slice(start, p.pos)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', text: normalizeInteger(token) }
  if (FLOAT_RE.test(token)) return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  p.fail(`invalid value ${token}`)
}

function parseValue(p, path) {
  if (p.atEnd() || isTerminator(p.peek())) p.fail('expected a value')
  const ch = p.peek()
  if (ch === '"') return { kind: 'string', value: parseBasicString(p) }
  if (ch === "'") return { kind: 'string', value: parseLiteralString(p) }
  if (ch === '[') return parseArrayValue(p, path)
  if (ch === '{') return parseInlineTableValue(p, path)
  return parseBareValue(p)
}

function parseArrayValue(p, path) {
  p.advance() // [
  const items = []
  let idx = 0
  for (;;) {
    p.skipWSAndComment()
    if (p.atEnd()) p.fail('unterminated array')
    if (p.peek() === ']') {
      p.advance()
      return { kind: 'array', items }
    }
    const val = parseValue(p, path.concat([{ kind: 'index', i: idx }]))
    items.push(val)
    idx++
    p.skipWSAndComment()
    if (p.atEnd()) p.fail('unterminated array')
    if (p.peek() === ',') {
      p.advance()
      continue
    }
    if (p.peek() === ']') {
      p.advance()
      return { kind: 'array', items }
    }
    p.fail('trailing text after a value')
  }
}

function assignInto(table, basePath, names, value, lineNumber) {
  let cur = table
  let segs = basePath.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    segs = segs.concat([{ kind: 'key', name }])
    if (cur.map.has(name)) {
      const existing = cur.map.get(name)
      if (existing.kind === 'table') cur = existing
      else if (existing.kind === 'aot') cur = existing.items[existing.items.length - 1]
      else throw new ParseError(lineNumber, `${pathStr(segs)} is not a table`)
    } else {
      const nt = makeTable()
      cur.map.set(name, nt)
      cur = nt
    }
  }
  const lastName = names[names.length - 1]
  const finalSegs = segs.concat([{ kind: 'key', name: lastName }])
  if (cur.map.has(lastName)) throw new ParseError(lineNumber, `key ${pathStr(finalSegs)} is defined twice`)
  cur.map.set(lastName, value)
}

function parseInlineTableValue(p, path) {
  p.advance() // {
  const table = makeTable()
  p.skipWSAndComment()
  if (p.atEnd()) p.fail('unterminated inline table')
  if (p.peek() === '}') {
    p.advance()
    return table
  }
  for (;;) {
    const names = parseDottedName(p)
    if (p.atEnd() || p.peek() !== '=') p.fail('expected = in an inline table')
    p.advance()
    p.skipWSAndComment()
    if (p.atEnd()) p.fail('expected a value')
    const entryPath = path.concat(names.map((name) => ({ kind: 'key', name })))
    const val = parseValue(p, entryPath)
    assignInto(table, path, names, val, p.lineNumber)
    p.skipWSAndComment()
    if (p.atEnd()) p.fail('unterminated inline table')
    if (p.peek() === ',') {
      p.advance()
      p.skipWSAndComment()
      if (p.atEnd()) p.fail('unterminated inline table')
      if (p.peek() === '}') p.fail('expected a name')
      continue
    }
    if (p.peek() === '}') {
      p.advance()
      return table
    }
    p.fail('trailing text after a value')
  }
}

function applyHeader(root, names, isArray, lineNumber) {
  let cur = root
  let segs = []
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    segs = segs.concat([{ kind: 'key', name }])
    if (cur.map.has(name)) {
      const existing = cur.map.get(name)
      if (existing.kind === 'table') cur = existing
      else if (existing.kind === 'aot') cur = existing.items[existing.items.length - 1]
      else throw new ParseError(lineNumber, `${pathStr(segs)} is not a table`)
    } else {
      const nt = makeTable()
      cur.map.set(name, nt)
      cur = nt
    }
  }
  const lastName = names[names.length - 1]
  const finalSegs = segs.concat([{ kind: 'key', name: lastName }])
  if (isArray) {
    if (cur.map.has(lastName)) {
      const existing = cur.map.get(lastName)
      if (existing.kind !== 'aot') throw new ParseError(lineNumber, `${pathStr(finalSegs)} is not an array of tables`)
      const nt = makeTable()
      existing.items.push(nt)
      return { table: nt, path: finalSegs.concat([{ kind: 'index', i: existing.items.length - 1 }]) }
    }
    const nt = makeTable()
    cur.map.set(lastName, { kind: 'aot', items: [nt] })
    return { table: nt, path: finalSegs.concat([{ kind: 'index', i: 0 }]) }
  }
  if (cur.map.has(lastName)) {
    const existing = cur.map.get(lastName)
    if (existing.kind !== 'table') throw new ParseError(lineNumber, `${pathStr(finalSegs)} is not a table`)
    if (existing.headerDefined) throw new ParseError(lineNumber, `table ${pathStr(finalSegs)} is defined twice`)
    existing.headerDefined = true
    return { table: existing, path: finalSegs }
  }
  const nt = makeTable(true)
  cur.map.set(lastName, nt)
  return { table: nt, path: finalSegs }
}

function parseHeaderLine(p, root) {
  p.advance() // first [
  let isArray = false
  if (!p.atEnd() && p.peek() === '[') {
    isArray = true
    p.advance()
  }
  const names = parseDottedName(p)
  if (p.atEnd() || p.peek() !== ']') p.fail('unterminated table header')
  p.advance()
  if (isArray) {
    if (p.atEnd() || p.peek() !== ']') p.fail('unterminated table header')
    p.advance()
  }
  p.skipWSAndComment()
  if (!p.atEnd()) p.fail('trailing text after a table header')
  return applyHeader(root, names, isArray, p.lineNumber)
}

function parseKeyValueLine(p, currentTable, currentPath) {
  const names = parseDottedName(p)
  if (p.atEnd() || p.peek() !== '=') p.fail('expected key = value')
  p.advance()
  p.skipWSAndComment()
  if (p.atEnd()) p.fail('expected a value')
  const fullPath = currentPath.concat(names.map((name) => ({ kind: 'key', name })))
  const value = parseValue(p, fullPath)
  p.skipWSAndComment()
  if (!p.atEnd()) p.fail('trailing text after a value')
  assignInto(currentTable, currentPath, names, value, p.lineNumber)
}

export function parseDocument(lines) {
  const root = makeTable(false)
  let currentTable = root
  let currentPath = []
  for (let idx = 0; idx < lines.length; idx++) {
    const lineNumber = idx + 1
    const raw = lines[idx]
    const firstIdx = findFirstNonWS(raw)
    if (firstIdx === -1) continue
    const ch0 = raw[firstIdx]
    if (ch0 === '#' || ch0 === ';') continue
    const p = new LineParser(raw, lineNumber)
    p.pos = firstIdx
    if (ch0 === '[') {
      const result = parseHeaderLine(p, root)
      currentTable = result.table
      currentPath = result.path
    } else {
      parseKeyValueLine(p, currentTable, currentPath)
    }
  }
  return root
}
