      else if (existing.kind === 'aot') cur = existing.items[existing.items.length - 1]
      else throw new ParseError(lineNumber, `${pathStr(segs)} is not a table`)
    } else {
      const nt = makeTable()
      cur.map.set(name, nt)
      cur = nt
    }
