    if (cur.map.has(lastName)) {
      const existing = cur.map.get(lastName)
      if (existing.kind !== 'aot') throw new ParseError(lineNumber, `${pathStr(finalSegs)} is not an array of tables`)
      const nt = makeTable()
      existing.items.push(nt)
