function jsonValue(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = [...node.map.keys()].sort(cmpCodePoint)
      if (keys.length === 0) return '{}'
      const nextIndent = indent + '  '
      const inner = keys
        .map((k) => `${nextIndent}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), nextIndent)}`)
        .join(',\n')
      return `{\n${inner}\n${indent}}`
    }
    case 'aot': {
      if (node.items.length === 0) return '[]'
      const nextIndent = indent + '  '
      const inner = node.items.map((it) => `${nextIndent}${jsonValue(it, nextIndent)}`).join(',\n')
      return `[\n${inner}\n${indent}]`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const nextIndent = indent + '  '
      const inner = node.items.map((it) => `${nextIndent}${jsonValue(it, nextIndent)}`).join(',\n')
      return `[\n${inner}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return jsonValue(root, '') + '\n'
}

function collectKeys(node, pathSegs, out) {
  if (node.kind === 'table') {
    if (pathSegs.length > 0) out.push(`${pathStr(pathSegs)} table`)
    const keys = [...node.map.keys()].sort(cmpCodePoint)
    for (const name of keys) collectKeys(node.map.get(name), pathSegs.concat([{ kind: 'key', name }]), out)
  } else if (node.kind === 'aot') {
    if (pathSegs.length > 0) out.push(`${pathStr(pathSegs)} array`)
    node.items.forEach((item, i) => collectKeys(item, pathSegs.concat([{ kind: 'index', i }]), out))
  } else if (node.kind === 'array') {
    out.push(`${pathStr(pathSegs)} array`)
    node.items.forEach((item, i) => collectKeys(item, pathSegs.concat([{ kind: 'index', i }]), out))
  } else {
    out.push(`${pathStr(pathSegs)} ${node.kind}`)
  }
}

export function toKeys(root) {
  const out = []
  collectKeys(root, [], out)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
